import{_ as t,o as e,c as o,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Tech Talk 2020-06-25: Solving the Bug of the Year","description":"","frontmatter":{"title":"Ceph Tech Talk 2020-06-25: Solving the Bug of the Year","date":"2020-06-25T00:00:00.000Z","updated":"2020-06-26T00:00:00.000Z","tags":["Ceph","Bug修复","分布式存储","内存ECC错误","LZ4压缩算法"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Tech_Talk_2020-06-25_-_Solving_the_Bug_of_the_Year.md","filePath":"posts/2020/Ceph_Tech_Talk_2020-06-25_-_Solving_the_Bug_of_the_Year.md","lastUpdated":1780459816000}'),p={name:"posts/2020/Ceph_Tech_Talk_2020-06-25_-_Solving_the_Bug_of_the_Year.md"};function r(_,l,n,s,a,g){return e(),o("div",null,[...l[0]||(l[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题：</strong> 解决年度Bug的技术分享</p><p><strong>主讲人：</strong> Dan（来自CERN IT部门）</p><p><strong>会议时间：</strong> 2020年6月25日</p><p><strong>会议地点：</strong> 线上</p><p><strong>参会人员：</strong> Ceph社区成员及相关技术人员</p><p><strong>会议内容总结：</strong></p><ol><li><p><strong>背景介绍：</strong></p><ul><li>CERN使用Ceph自2013年起，作为其IT基础设施的关键部分，用于OpenStack的块存储和对象存储。</li><li>CERN拥有约10个Ceph集群，总存储容量达35 PB。</li></ul></li><li><p><strong>问题描述：</strong></p><ul><li>2020年2月20日，CERN的OpenStack块存储系统出现严重故障，25%的OSD失效，导致所有I/O操作被阻塞。</li><li>问题根源在于OSD映射（OSD map）存在CRC错误。</li></ul></li><li><p><strong>诊断与解决过程：</strong></p><ul><li>通过Ceph社区的帮助，快速定位到一个已知的相关问题，并找到了一个临时解决方案。</li><li>使用Mon节点提取未损坏的OSD映射版本，覆盖损坏的版本，恢复了集群的运行。</li><li>通过分析发现，损坏的OSD映射存在多个比特位翻转，怀疑是内存ECC错误、网络包损坏或软件bug。</li></ul></li><li><p><strong>根本原因分析：</strong></p><ul><li>排除了内存ECC错误和网络包损坏的可能性。</li><li>发现问题与LZ4压缩算法有关，特别是当压缩未对齐的内存时，可能导致数据损坏。</li><li>与LZ4开发者合作，确认了问题并找到了修复方案。</li></ul></li><li><p><strong>后续行动计划：</strong></p><ul><li>计划引入块存储可用性区域，以提高系统的容错能力。</li><li>将持续关注Ceph社区的更新，并考虑升级操作系统中的LZ4库版本。</li></ul></li></ol><p><strong>感谢与致谢：</strong></p><ul><li>感谢Ceph社区成员，特别是Dirtwash、Troy和Eric的帮助。</li><li>感谢CERN IT团队的同事们，以及LZ4算法的开发者。</li></ul><p><strong>会议结束：</strong></p><ul><li>会议内容将被录制并上传至YouTube。</li></ul><p><strong>备注：</strong></p><ul><li>本次会议详细讨论了Ceph集群中遇到的一个罕见但严重的Bug，以及如何通过社区合作和技术分析找到并解决问题的过程。</li></ul>',14)])])}const C=t(p,[["render",r]]);export{u as __pageData,C as default};
